	if (!config.enabled || isMemorySubAgentCtx(ctx)) return;
	journal.toolCounts.set(event.toolName, (journal.toolCounts.get(event.toolName) ?? 0) + 1);
	// v3: pollution tracking — web/MCP tools taint the session.
	recordToolForPollution(pollution, event.toolName);
	if (pollution.count > 0) memoryDb?.markSessionPolluted(originSessionId, [...pollution.tools]);
	recordObservation("tool_call", event.toolName, { input: summarizeToolInput(event.input) });
});

pi.on("tool_result", (event, ctx) => {
	if (!config.enabled || isMemorySubAgentCtx(ctx)) return;
